#!/usr/bin/env python3
"""Escreve relatório científico B2 a partir dos resumos processados e manifesto."""
from pathlib import Path
import json,pandas as pd
ROOT=Path(__file__).resolve().parents[3];OUT=ROOT/'reports/b2_combined_characterization_20261112'
S=pd.read_csv(OUT/'processed/summary.csv').set_index(['id','class']);P=pd.read_csv(OUT/'processed/phase_summary.csv').set_index(['id','class','phase']);I=pd.read_csv(OUT/'processed/infrastructure_summary.csv').set_index('id');M=json.loads((OUT/'manifest.json').read_text());INV=pd.read_csv(OUT/'inventario_execucoes.csv')
def n(k,c,f):
 v=S.loc[(k,c),f];return '—' if pd.isna(v) else (f'{v:.2f}' if isinstance(v,float) else str(v))
def i(k,f):return f'{I.loc[k,f]:.2f}'
lines=['# Caracterização experimental B2 — tráfego combinado','','## Escopo, inventário e comparabilidade','','Foram auditadas quatro execuções B2 completas e três referências isoladas históricas. Todas possuem topologia direta, vítima única, dois workers, duração configurada de 150 s e instrumentação Docker/HTTP. PRE=[0,30), ACTIVE=[30,60) e POST=[60,150) s. A1-L2 não tem fase ofensiva; a janela [30,60) é usada apenas como referência temporal. A B1-A3 é a referência isolada de assimetria a **8 RPS agregados** (2×4); B1-F2 é Flooding a **64 RPS agregados** (2×32). A1-L2 e B2-L são duas execuções legítimas distintas.','','| Execução | Papel | Legítimas | Ofensivas | Concorrência ofensiva | Endpoint ofensivo | HTTP observados |','|---|---|---:|---:|---:|---|---:|']
for _,r in INV.iterrows():lines.append(f"| {r.id} | {r.role} | {r.legitimate_nominal_rps:.0f} RPS, {r.legitimate_sources} fontes | {r.attack_nominal_rps:.0f} RPS, {r.attack_sources} fontes | {int(r.attack_concurrency) if pd.notna(r.attack_concurrency) else '—'} | {r.attack_endpoint if pd.notna(r.attack_endpoint) else '—'} | {r.request_rows} |")
lines+=['','As referências históricas são elegíveis para comparação **visual descritiva**, não para subtração causal. Memória da A1-L2 difere do patamar B2-L; não se deve atribuir essa diferença à combinação de cargas. B2-F e B2-F96 possuem configuração efetiva igual, salvo a concorrência ofensiva (64 e 96), mas foram executadas uma vez cada em momentos sucessivos.','','## Definições e relógios','','- `request_log.csv.elapsed_seconds` e `end_elapsed_seconds` são tempos relativos ao início da execução no cliente. RPS iniciado conta inícios no intervalo semiaberto [30,60) e divide por 30 s. RPS encerrado conta encerramentos pelo seu próprio timestamp. Desfechos da coorte ACTIVE classificam tentativas iniciadas em [30,60), mesmo que terminem depois de 60 s.','','- `outcome=response` com status 2xx é sucesso HTTP observado; `ReadTimeout` é timeout do cliente. Um timeout não implica encerramento do processamento na vítima. Tarefas submetidas e sem início HTTP são mostradas separadamente.','','- CPU Docker é `victim_stats.jsonl.metrics.cpu_percent` da `target_instance_1`; pode exceder 100% em múltiplos núcleos. Memória é `raw_mem_usage/1048576` MiB do contêiner, não do host ou do processo Python. Amostras reais são desenhadas sem interpolação.','','- Operações são ligadas por `operation_id` e `request_id`. Espera = `work_started - work_submitted`; execução decorrida = `work_completed - work_started`; CPU/operação = `work_cpu_seconds × 1000`. A A1-L2 usa os timestamps consolidados em `handler_finished`, pois não dispõe dos eventos explícitos de work.','','- Workers ocupados e operações aguardando são reconstruídos por eventos de submissão, início e conclusão, com eventos simultâneos agrupados. A quantidade aguardando mede operações submetidas ainda sem início, não a profundidade exata da fila interna. Não há medição direta da espera pré-handler.','','- Eventos da vítima e fontes usam `CLOCK_MONOTONIC` do host, com origem `experiment_start_monotonic`; o log HTTP fornece o tempo relativo já calculado pela execução. Eventos de `traffic_class=unknown` antes do tráfego são auditoria/captura e foram excluídos. Captura TCP não separa classes com confiabilidade e `packet_length` não é byte no fio.','','## Atendimento legítimo e fase ofensiva','','| Condição | Inícios HTTP | RPS iniciado | HTTP 2xx | Timeout | Duração mediana 2xx (ms) | p95 2xx (ms) | Espera mediana (ms) |','|---|---:|---:|---:|---:|---:|---:|---:|']
for k in ['B2-L','B2-A','B2-F','B2-F96']:lines.append(f"| {k} | {n(k,'benign','started_active')} | {n(k,'benign','rps_started_active')} | {n(k,'benign','http_2xx_active_cohort')} | {n(k,'benign','timeouts_active_cohort')} | {n(k,'benign','http_success_median_ms')} | {n(k,'benign','http_success_p95_ms')} | {n(k,'benign','work_wait_median_ms')} |")
lines+=['','A taxa legítima iniciada ficou próxima de 17,13–17,17 RPS nas quatro condições, acima do nominal de 16 RPS. B2-A e B2-F96 preservaram os inícios legítimos durante ACTIVE, mas grande parte das tentativas terminou em timeout. B2-F manteve respostas 2xx para toda a coorte ACTIVE, com duração mediana muito superior à B2-L. A mediana dos sucessos sobreviventes em B2-A e B2-F96 não descreve o atendimento global, pois poucos sucessos permaneceram.','','## Tráfego ofensivo e processamento','','| Condição | RPS nominal | RPS iniciado | HTTP 2xx da coorte | Timeout da coorte | Submetidas sem HTTP | CPU/op mediana (ms) | Espera mediana (ms) |','|---|---:|---:|---:|---:|---:|---:|---:|']
for k in ['B1-A3','B2-A','B1-F2','B2-F','B2-F96']:lines.append(f"| {k} | {n(k,'attack','nominal_rps')} | {n(k,'attack','rps_started_active')} | {n(k,'attack','http_2xx_active_cohort')} | {n(k,'attack','timeouts_active_cohort')} | {n(k,'attack','submitted_not_http')} | {n(k,'attack','work_cpu_median_ms')} | {n(k,'attack','work_wait_median_ms')} |")
lines+=['','A B2-A registrou espera computacional mediana elevada para ambas as classes e 471 timeouts legítimos na fase ACTIVE. O trabalho da vítima pode continuar após o timeout do cliente. B2-F e B2-F96 compartilham o endpoint `/medium` com o tráfego legítimo; a distinção entre classes foi feita pelos IDs e pelo campo `traffic_class`, não pelo endpoint. Em B2-F, 191 tarefas ofensivas submetidas não chegaram ao início HTTP; em B2-F96 foram 308. Essas tarefas não são timeouts HTTP.','','## CPU Docker, CPU por operação e memória','','| Condição | CPU Docker média ACTIVE (%) | CPU mediana (%) | CPU máxima (%) | Memória média (MiB) | Memória máxima (MiB) | Fração com 2 workers | Máximo aguardando ACTIVE |','|---|---:|---:|---:|---:|---:|---:|---:|']
for k in ['B2-L','B2-A','B2-F','B2-F96']:lines.append(f"| {k} | {i(k,'cpu_mean_active_pct')} | {i(k,'cpu_median_active_pct')} | {i(k,'cpu_max_active_pct')} | {i(k,'mem_mean_active_mib')} | {i(k,'mem_max_active_mib')} | {100*I.loc[k,'workers_two_fraction_active']:.1f}% | {I.loc[k,'waiting_max_active']:.0f} |")
lines+=['','### Memória por fase','','| Condição | PRE mediana (MiB; n) | ACTIVE mediana (MiB; n) | POST mediana (MiB; n) | POST − PRE (MiB) |','|---|---:|---:|---:|---:|']
for k in ['B2-L','B2-A','B2-F','B2-F96']:
 st=pd.read_csv(OUT/'processed'/f'stats_{k}.csv');v=[]
 for l,h in [(0,30),(30,60),(60,150)]:
  z=st[(st.t>=l)&(st.t<h)];v.append((z.mem.median(),len(z)))
 lines.append(f'| {k} | {v[0][0]:.2f} (n={v[0][1]}) | {v[1][0]:.2f} (n={v[1][1]}) | {v[2][0]:.2f} (n={v[2][1]}) | {v[2][0]-v[0][0]:+.2f} |')
lines+=['','As diferenças POST − PRE são descritivas da memória do contêiner e não identificam a origem da alocação.']
lines+=['','A ocupação de dois workers foi observada por menos tempo na B2-L que nas três condições com ataque. As medianas de CPU por operação e de espera são métricas distintas: a espera pode crescer sem aumento equivalente do tempo de CPU individual. A memória medida é a do contêiner inteiro; a comparação por fase e as matrizes mostram a evolução e possíveis resíduos após o ataque sem atribuição a uma classe específica.','','## Evolução por fase e recuperação','','| Condição | Fase | Inícios legítimos | HTTP 2xx | Timeouts | Duração mediana 2xx (ms) |','|---|---|---:|---:|---:|---:|']
for k in ['B2-L','B2-A','B2-F','B2-F96']:
 for p in ['PRE','ACTIVE','POST']:
  r=P.loc[(k,'benign',p)];lines.append(f"| {k} | {p} | {r.started:.0f} | {r.http_2xx_start_cohort:.0f} | {r.timeout_start_cohort:.0f} | {r.success_median_ms:.2f} |")
lines+=['','### Eventos nos limites da execução','','| Condição | Inícios HTTP em ou após 150 s | Encerramentos após 150 s |','|---|---:|---:|']
for k in ['B2-L','B2-A','B2-F','B2-F96']:
 r=pd.read_csv(OUT/'processed'/f'requests_{k}.csv');lines.append(f'| {k} | {(r.elapsed_seconds>=150).sum()} | {(r.end_elapsed_seconds>150).sum()} |')
lines+=['','Esses registros permanecem nos dados processados. Inícios em ou após 150 s não entram nas taxas por fase; encerramentos posteriores não são deslocados artificialmente para a janela anterior.']
lines+=['','As contagens por fase são atribuídas pelo instante de início HTTP. A B2-A registrou 476 timeouts legítimos entre requisições iniciadas em POST, evidenciando persistência da degradação após 60 s; B2-F96 registrou 28 e B2-F, nenhum. Um timeout iniciado próximo do fim de ACTIVE pode ocorrer em POST; os painéis de atendimento mostram encerramentos pelo instante do evento. As séries de CPU e memória preservam a cadência real das amostras Docker.','','## F64 versus F96','','A comparação específica registra RPS ofensivo iniciado de '+n('B2-F','attack','rps_started_active')+' em F64 e '+n('B2-F96','attack','rps_started_active')+' em F96. Os sucessos legítimos da coorte ACTIVE foram '+n('B2-F','benign','http_2xx_active_cohort')+' e '+n('B2-F96','benign','http_2xx_active_cohort')+', enquanto os timeouts foram '+n('B2-F','benign','timeouts_active_cohort')+' e '+n('B2-F96','benign','timeouts_active_cohort')+'. Esses dados são compatíveis com a observação exploratória de menor atendimento legítimo em F96 sem aumento do RPS ofensivo iniciado. Eles não isolam a concorrência como causa, pois não há repetição nem controle completo das condições ambientais. O relatório histórico da B2-F96 sugeria concorrência 64; a decisão posterior por 96 deve ser documentada cientificamente fora desta caracterização.','','## Limitações metodológicas','','Há uma realização por condição; amostras temporais e operações dentro da mesma execução não são repetições experimentais independentes. A1 e B1 foram realizadas em campanhas diferentes. B1-A3 e B1-F2 têm apenas tráfego ofensivo, o que muda a composição da carga. As condições ofensivas diferem em endpoint, intensidade e custo por operação. O endpoint `/expensive` não difere do `/medium` apenas por rótulo; parâmetros de trabalho podem variar. A CPU Docker tem cadência de cerca de 3 s e não é atribuível a uma classe. A duração HTTP inclui rede, cliente, espera pré-handler não medida, espera de worker e processamento. Timeouts não equivalem a falha ou interrupção do processamento da vítima. A captura TCP representa tráfego total e não foi atribuída a classes.','','## Catálogo de figuras','','Cada linha abaixo corresponde a uma figura em PNG de 300 dpi e PDF vetorial. As composições históricas são adequadas para contextualização visual; os painéis B2 e as figuras de degradação são candidatos à seleção posterior, sem seleção nesta etapa.','','| Figura | Pergunta | Fonte | Métricas e cálculo | Observação | Limitação | Uso potencial |','|---|---|---|---|---|---|---|']
def catalog(p):
 if 'b2_individuais/' in p:
  k=next(k for k in ['B2-L','B2-A','B2-F','B2-F96'] if k in p)
  return ('B2: request_log, victim_stats, eventos de work', 'RPS em 1 s; Docker nos timestamps reais; estados de workers por eventos; HTTP individual', f'{k}: {n(k,"benign","http_2xx_active_cohort")} sucessos e {n(k,"benign","timeouts_active_cohort")} timeouts legítimos em ACTIVE', 'Uma execução; associação temporal descritiva', 'Visão integrada')
 if 'composicao_cargas/' in p:
  return ('A1-L2 ou B2-L; B1-A3/F2; B2-A/F/F96', 'Três colunas de séries temporais; mesma escala vertical por linha', 'Recursos e atendimento nas cargas isoladas e combinadas', 'Campanhas históricas; sem soma de CPU/memória', 'Contexto de cargas')
 if 'flooding_64_vs_96/' in p:
  return ('B2-F e B2-F96: request_log, Docker, work', 'Indicadores ou séries por condição; coorte ACTIVE quando agregado', 'F96: 49,87 RPS ofensivos e 416 timeouts legítimos; F64: 54,07 RPS e 0 timeouts', 'Uma execução por concorrência', 'Comparação de concorrência')
 if 'degradacao_legitima/' in p:
  return ('B2: request_log; work quando indicado', 'Desfechos por coorte; duração 2xx e timeout separadas; ECDF/boxplot/fases', 'B2-A e B2-F96 tiveram mais timeouts; B2-F teve maior duração de respostas', 'Sucessos sobreviventes não representam todas as tentativas', 'Atendimento legítimo')
 if 'cpu/' in p:
  return ('B2: victim_stats e eventos de work', 'Amostras Docker reais; CPU/operação por evento; fases ou distribuições', 'CPU Docker ACTIVE foi maior nas condições com ataque que na B2-L', 'CPU Docker não é CPU por classe; sem inferência causal', 'Pressão computacional')
 if 'memoria/' in p or 'matriz_mem' in p:
  return ('B2: victim_stats.raw_mem_usage', 'Conversão bytes/1048576; amostras reais e distribuições', 'Memória variou em todas as execuções, inclusive B2-L', 'Memória do contêiner, não atribuível a classe', 'Uso de memória')
 if 'workers/' in p or 'matriz_run' in p or 'matriz_wait' in p:
  return ('B2: work_submitted/started/completed', 'Reconstrução orientada a eventos; frações de tempo e espera em ms', 'Dois workers ficaram ocupados por >97% da fase ACTIVE nas condições ofensivas', 'Aguardando não é profundidade exata da fila interna', 'Disputa computacional')
 if 'rede_' in p or 'matriz_network' in p:
  return ('B2: traffic_capture.csv', 'Contagem de pacotes TCP em janelas de 1 s', 'A captura permite inspecionar variação temporal do volume', 'Pacotes não são requisições HTTP; classe não atribuída', 'Contexto de rede')
 if 'matriz_rps' in p or 'matriz_outcomes' in p:
  return ('B2: request_log.csv', 'Eventos HTTP em janelas de 1 s pelo timestamp próprio', 'Inícios legítimos persistiram; respostas e timeouts diferiram', 'Taxas de início e encerramento têm critérios distintos', 'Atendimento temporal')
 if 'matriz_duration' in p:
  return ('B2: request_log.csv', 'Pontos individuais por início HTTP; 2xx e timeout separados', 'A duração legítima cresceu durante as condições ofensivas', 'Timeout é tempo até encerramento no cliente', 'Duração HTTP')
 if 'matriz_cpuop' in p or 'matriz_waitms' in p:
  return ('B2: eventos de work', 'Pontos individuais por instante de submissão', 'Operações legítimas e ofensivas mostram custos e esperas distintos', 'Espera de worker não é espera HTTP total', 'Operações computacionais')
 return ('B2: registros primários conforme manifesto', 'Série ou distribuição descritiva indicada pelo eixo', 'Comparação temporal entre quatro condições', 'Uma execução por condição', 'Inspeção exploratória')
for f in M['figures']:
 p=f['path'];source,method,observation,limit,use=catalog(p)
 lines.append(f'| [{Path(p).stem}]({p}.png) | {f["question"]} | {source} | {method} | {observation} | {limit} | {use} |')
lines+=['','## Reprodução e validação','','Da raiz do repositório:','','```bash','python3 reports/b2_combined_characterization_20261112/scripts/generate.py','python3 reports/b2_combined_characterization_20261112/scripts/write_report.py','python3 reports/b2_combined_characterization_20261112/scripts/validate.py','```','','Dependências: Python 3, pandas, NumPy, Matplotlib e Pillow (para validação dos PNG). O manifesto registra SHA-256 dos arquivos primários e scripts, parâmetros e saídas. `validation/checks.json` e `validation/result.json` documentam as verificações. Entradas originais são somente leitura.']
(OUT/'relatorio.md').write_text('\n'.join(lines)+'\n')
(OUT/'README.md').write_text('# Caracterização B2\n\nQuatro execuções B2 e três referências históricas auditadas em artefatos primários. Consulte [relatorio.md](relatorio.md), [manifest.json](manifest.json) e [validation/result.json](validation/result.json).\n\nReprodução da raiz do repositório:\n\n```bash\npython3 reports/b2_combined_characterization_20261112/scripts/generate.py\npython3 reports/b2_combined_characterization_20261112/scripts/write_report.py\npython3 reports/b2_combined_characterization_20261112/scripts/validate.py\n```\n\nDependências: Python 3, pandas, NumPy, Matplotlib e Pillow. Todas as saídas são gravadas nesta pasta.\n')
print(f'Relatório com {len(M["figures"])} figuras.')
